def find_conflicts(sessions: Sequence[Session]) -> List[Tuple[Session, Session]]:
    """Return every pair of sessions that clash (same day, same room or group, overlapping time)."""
    conflicts = []
    for i, a in enumerate(sessions):
        for j in range(i + 1, len(sessions)):
            b = sessions[j]
            # Sessions must be on the same day
            if a.day != b.day:
                continue
            # Check overlapping times (touching endpoints do not count) and shared resource
            if a.overlaps(b) and _shares_resource(a, b):
                conflicts.append((a, b))
    return conflicts
